package com.cdac.cssip.auth.config; import com.cdac.cssip.auth.entity.ValidId;import com.cdac.cssip.auth.repository.ValidIdRepository;import com.cdac.cssip.common.enums.Role;import com.cdac.cssip.common.security.JwtTokenService;import org.springframework.beans.factory.annotation.Value;import org.springframework.boot.CommandLineRunner;import org.springframework.context.annotation.*;import org.springframework.security.config.annotation.web.builders.HttpSecurity;import org.springframework.security.crypto.bcrypt.*;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.security.web.SecurityFilterChain;
@Configuration public class AuthConfig{@Bean PasswordEncoder pe(){return new BCryptPasswordEncoder();}@Bean JwtTokenService jwt(@Value("${jwt.secret}")String s,@Value("${jwt.expiration}")long e){return new JwtTokenService(s,e);}@Bean SecurityFilterChain c(HttpSecurity h)throws Exception{return h.csrf(x->x.disable()).authorizeHttpRequests(a->a.anyRequest().permitAll()).build();}@Bean CommandLineRunner seed(ValidIdRepository r){return a->{for(var x:new Object[][]{{"ADMIN001",Role.ADMIN},{"STAFF001",Role.STAFF},{"STUDENT001",Role.STUDENT},{"STUDENT002",Role.STUDENT}})if(r.findByCdacId((String)x[0]).isEmpty())r.save(ValidId.builder().cdacId((String)x[0]).role((Role)x[1]).used(((String)x[0]).equals("ADMIN001")).build());};}}
